WITH employees_by_department AS (SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary, SUM(CASE WHEN level = 'L5' THEN salary ELSE 0 END) AS l5_salary FROM employees WHERE manager_id IN (5, 10, 20) GROUP BY dept_id) SELECT departments.dept_name, employees_by_department.stddev_salary, employees_by_department.l5_salary FROM departments INNER JOIN employees_by_department ON departments.id = employees_by_department.dept_id WHERE employees_by_department.l5_salary >= 73 ORDER BY l5_salary DESC;
